import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Plane geometry based on image aspect (512:320 ≈ 1.6:1)
  const plane = new Mesh(
    new PlaneGeometry(1.6, 1),
    new MeshBasicNodeMaterial({ transparent: true })
  );

  root.add(plane);

  // Load texture synchronously (promise handled internally)
  let loadedTexture = null;
  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      // Assign texture node to material color
      plane.material.color = texture(tex);
      plane.material.needsUpdate = true;
    })
    .catch(() => {
      // Fail silently; plane will remain untextured
    });

  // No cinematic primitives to apply for this node

  // Event handlers placeholder (none defined)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry
    if (plane.geometry) plane.geometry.dispose();

    // Dispose material
    if (plane.material) plane.material.dispose();

    // Dispose texture if it was loaded
    if (loadedTexture) loadedTexture.dispose();

    // Kill any GSAP timelines (none used but defensive)
    gsap.globalTimeline.clear();
  };

  return root;
}
